&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;Hands&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;-&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;on experience with&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;pharmacovigilance systems and&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;safety database&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;s&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;, including validation, audits, and compliance assessments&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:147}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;Proven experience in developing and implementing risk-based clinical quality assurance programs&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:147}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;Experience leading PVQA audits and&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;inspections and&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;&amp;nbsp;responding to regulatory findings&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:147}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;Ability&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;to concisely&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;&amp;nbsp;present quality events to internal stakeholders&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:147}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;Results-oriented, with a focus on setting&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;objectives&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;&amp;nbsp;and&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;effectively&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;manage&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;&amp;nbsp;competing priorities and dynamic timelines&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:147}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
